\set ON_ERROR_STOP on
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE public.users (uuid UUID PRIMARY KEY, email TEXT NOT NULL DEFAULT '', username TEXT NOT NULL DEFAULT '', password TEXT NOT NULL DEFAULT '', proxy_uuid UUID NULL);
CREATE TABLE public.subscriptions (uuid UUID PRIMARY KEY, user_uuid UUID NOT NULL, provider TEXT NOT NULL, payment_method TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL, status TEXT NOT NULL, plan_id TEXT NOT NULL, external_id TEXT NOT NULL DEFAULT '', meta JSONB NOT NULL DEFAULT '{}');
CREATE TABLE public.finance_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), idempotency_key TEXT NOT NULL UNIQUE, account_uuid UUID NOT NULL, subscription_uuid UUID NOT NULL, provider TEXT NOT NULL, provider_invoice_id TEXT NOT NULL UNIQUE, amount_minor BIGINT NOT NULL, currency TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', issued_at TIMESTAMPTZ NOT NULL DEFAULT now(), due_at TIMESTAMPTZ NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE FUNCTION public.reject_finance_fact_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only'; END; $$;
CREATE TRIGGER finance_invoices_append_only BEFORE UPDATE OR DELETE ON public.finance_invoices FOR EACH ROW EXECUTE FUNCTION public.reject_finance_fact_mutation();
CREATE TABLE public.finance_payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), idempotency_key TEXT NOT NULL UNIQUE, invoice_id UUID NOT NULL, account_uuid UUID NOT NULL, provider TEXT NOT NULL, provider_payment_id TEXT NOT NULL, amount_minor BIGINT NOT NULL, currency TEXT NOT NULL, paid_at TIMESTAMPTZ NOT NULL);
CREATE TABLE public.finance_refunds (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), idempotency_key TEXT NOT NULL UNIQUE, payment_id UUID NOT NULL, provider TEXT NOT NULL, provider_refund_id TEXT NOT NULL DEFAULT '', amount_minor BIGINT NOT NULL, currency TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', refunded_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.finance_operations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), idempotency_key TEXT NOT NULL UNIQUE, operation_type TEXT NOT NULL, target_type TEXT NOT NULL DEFAULT '', target_id TEXT NOT NULL DEFAULT '', provider TEXT NOT NULL DEFAULT 'local', provider_operation_id TEXT NULL, status TEXT NOT NULL DEFAULT 'pending', attempt_count INTEGER NOT NULL DEFAULT 0, next_attempt_at TIMESTAMPTZ NULL, last_error TEXT NOT NULL DEFAULT '', request JSONB NOT NULL DEFAULT '{}'::jsonb, response JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
\ir ../2026101301_referral_program.up.sql
